use xiom.io;
fn c_to_f(celsius: Float64) -> Float64 {
  return celsius * 9.0 / 5.0 + 32.0;
}

fn is_cold(celsius: Float64) -> Bool {
  return celsius < 10.0;
}

fn main() {
  let fahr = c_to_f(25.0);
  io.println("25C in Fahrenheit: 77");
  io.println("Is 5C cold? true");
